def verify_isbn(isbn: str) -> str:
    isbn_list = isbn.split('-')
    if len(isbn_list) != 4:
        return "Wrong format"
    checksum = isbn_list.pop()
    if checksum.isdigit():
        checksum = int(checksum)
    else:
        return "Wrong format"
    isbn_list = [int(i) for i in isbn_list]
    total = sum(isbn_list) * 10
    if total % 11 == checksum:
